11	    static void sort(int[] values) {
12	        Objects.requireNonNull(values, "values");
13	
14	        int n = values.length;
15	        if (n < 2) {
16	            return;
17	        }
18	
19	        for (int pass = 0; pass < n - 1; pass++) {
20	            boolean swapped = false;
21	
22	            for (int index = 0; index < n - pass - 1; index++) {
23	                if (isOutOfOrder(values[index], values[index + 1])) {
24	                    swap(values, index, index + 1);
25	                    swapped = true;
26	                }
27	            }
28	
29	            if (!swapped) {
30	                break;
31	            }
32	        }
33	    }
34	
35	    private static boolean isOutOfOrder(int left, int right) {
36	        return left > right;
37	    }
38	
39	    private static void swap(int[] values, int left, int right) {
40	        int temp = values[left];
41	        values[left] = values[right];
42	        values[right] = temp;
43	    }
44	
45	    static void printArray(int[] values) {
46	        System.out.println(formatValues(values));
47	    }
48	
49	    private static String formatValues(int[] values) {
50	        StringJoiner joiner = new StringJoiner(" ");
51	
52	        for (int value : values) {
53	            joiner.add(Integer.toString(value));
54	        }
55	
56	        return joiner.toString();
57	    }
